        },
        "Status": {
          "$ref": "#/components/schemas/AEConsentStatus.AEConsentStatusCodes"
        },
        "StatusUpdateDateTime": {
          "$ref": "#/components/schemas/AEConsentStatus.AEStatusUpdateDateTime"
        },
        "Permissions": {
          "type": "array",
          "items": {
            "$ref": "#/components/schemas/AEBankDataSharingConsentPermissionCodes"
          },
          "minItems": 1
        },
        "ExpirationDateTime": {
          "$ref": "#/components/schemas/AEPushedAuthorizationRequests.AEConsentExpirationDateTime"
        },
        "TransactionFromDateTime": {
          "type": "string",
          "format": "date-time",
          "description": "**DEPRECATED AT V2.1, REPLACED BY `FromDate`**",
          "deprecated": true
        },
        "TransactionToDateTime": {
          "type": "string",
          "format": "date-time",
          "description": "**DEPRECATED AT V2.1, REPLACED BY `ToDate`**",
          "deprecated": true
        },
        "FromDate": {
          "$ref": "#/components/schemas/AEBankDataSharingRichAuthorizationRequests.AEBankDataSharingFromDate"
        },
        "ToDate": {
          "$ref": "#/components/schemas/AEBankDataSharingRichAuthorizationRequests.AEBankDataSharingToDate"
        },
        "AccountType": {
          "type": "array",
          "items": {
            "$ref": "#/components/schemas/AEBankDataSharing.AEExternalAccountTypeCode"
          }
        },
        "AccountSubType": {
          "type": "array",
          "items": {
            "$ref": "#/components/schemas/AEBankDataSharing.AEExternalAccountSubTypeCode"
          },
          "description": "Account Sub Types permitted under the consent."
        },
        "OnBehalfOf": {
          "$ref": "#/components/schemas/AEBankDataSharingRichAuthorizationRequests.OnBehalfOf"
        },
        "OpenFinanceBilling": {
          "$ref": "#/components/schemas/AEConsentStatus.AEBankDataSharingOpenFinanceBilling"
        },
        "RevokedBy": {
          "$ref": "#/components/schemas/AEConsentStatus.AERevokedByCodes"
        }
      },
      "required": [
        "ConsentId",
        "CreationDateTime",
        "Status",
        "StatusUpdateDateTime",
        "Permissions",
        "ExpirationDateTime",
        "OpenFinanceBilling"
      ],
      "additionalProperties": false
    },
    "Subscription": {
      "$ref": "#/components/schemas/AEStandardModels.AEEventNotification"
    },
    "Links": {
      "$ref": "#/components/schemas/AEStandardModels.AELinksSelf"
    },
    "Meta": {
      "$ref": "#/components/schemas/AEStandardModels.AEMeta"
    }
  },
  "additionalProperties": false
}

{
  "type": "string",
  "minLength": 1,
  "maxLength": 128,
  "description": "Unique identification assigned by the TPP to identify the Consent."
}

{
  "type": "string",
  "minLength": 1,
  "maxLength": 128,
  "description": "The original ConsentId assigned by the TPP.\nIt is used by the TPP for updating/renewing parameters associated with long-lived consents.\nIt must be provided when long-lived consent parameters are updated/renewed for a current consent that has not yet finished."
}

{
  "type": "string",
  "format": "date-time",
  "description": "Date and time at which the Consent was created. All dates in the JSON payloads are represented in ISO 8601 date-time format.\n\nAll date-time fields in responses must include the timezone, for example: 2023-04-05T10:43:07+00:00"
}

{
  "type": "string",
  "format": "date-time",
  "description": "Date and time at which the resource status was updated. All dates in the JSON payloads are represented in ISO 8601 date-time format.\n\nAll date-time fields in responses must include the timezone, for example: 2023-04-05T10:43:07+00:00"
}

{
  "type": "string",
  "format": "date-time",
  "description": "Specified date and time the consent will expire.\n\nAll dates in the JSON payloads are represented in ISO 8601 date-time format.\n\nAll date-time fields in responses must include the timezone, for example: 2023-04-05T10:43:07+00:00"
}

{
  "type": "string",
  "format": "date",
  "description": "Specified start date for the transaction or statement query period.\n\nIf this is not populated, the start date will be open ended, and data will be returned from the earliest available transaction or statement.\n\nAll dates in the JSON payloads are represented in ISO 8601 date format.  For example: 2025-01-01"
}

{
  "type": "string",
  "format": "date",
  "description": "Specified end date for the transaction or statement query period.\n\nIf this is not populated, the end date will be open ended, and data will be returned to the latest available transaction or the last statement generated.\n\nAll dates in the JSON payloads are represented in ISO 8601 date format.  For example: 2025-12-31    "
}

{
  "type": "string",
  "enum": [
    "Retail",
    "SME",
    "Corporate"
